const STORAGE = {
  user: 'al-madraj-platform-user',
  enrollments: 'al-madraj-platform-enrollments',
  progress: 'al-madraj-platform-progress',
  pendingCourse: 'al-madraj-platform-pending-course',
};
const ADMIN_COURSES_STORAGE = 'al-madraj-admin-courses';
const ADMIN_LESSONS_STORAGE = 'al-madraj-admin-lessons';

const readStorage = <T,>(key: string, fallback: T): T => {
  try {
    const value = window.localStorage.getItem(key);
    return value ? JSON.parse(value) as T : fallback;
  } catch {
    return fallback;
  }
};

const writeStorage = (key: string, value: unknown) => window.localStorage.setItem(key, JSON.stringify(value));
const defaultManagedCourses = (): ManagedCourse[] => courses.map((course) => ({ ...course, published: true }));
const courseFromPath = (path: string) => courses.find((course) => path.split('/')[2] === course.id) || courses[0];

export const PlatformPage: React.FC = () => {
  const [path, setPath] = useState(window.location.pathname + window.location.search);
  const [user, setUser] = useState<User | null>(() => readStorage<User | null>(STORAGE.user, null));
  const [enrollments, setEnrollments] = useState<Enrollment[]>(() => readStorage<Enrollment[]>(STORAGE.enrollments, []));

  useEffect(() => {
    const onPopState = () => setPath(window.location.pathname + window.location.search);
    window.addEventListener('popstate', onPopState);
    return () => window.removeEventListener('popstate', onPopState);
  }, []);

  const go = (nextPath: string) => {
    window.history.pushState(null, '', nextPath);
    setPath(nextPath);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const saveUser = (nextUser: User) => {
    writeStorage(STORAGE.user, nextUser);
    setUser(nextUser);
    const pending = window.localStorage.getItem(STORAGE.pendingCourse);
    if (pending) {
      window.localStorage.removeItem(STORAGE.pendingCourse);
      go('/checkout/' + pending);
    } else {
      go('/dashboard');
    }
  };

  const logout = () => {
    window.localStorage.removeItem(STORAGE.user);
    setUser(null);
    go('/login');
  };

  const requestCourse = (course: Course) => {
    if (!user) {
      window.localStorage.setItem(STORAGE.pendingCourse, course.id);
      go('/login');
      return;
    }
    go('/checkout/' + course.id);
  };

  const completePayment = (course: Course, payment: PaymentMethod) => {
    const next: Enrollment = { courseId: course.id, status: 'Aktif', payment, createdAt: new Date().toISOString() };
    const updated = [...enrollments.filter((item) => item.courseId !== course.id), next];
    writeStorage(STORAGE.enrollments, updated);
    setEnrollments(updated);
    go('/dashboard');
  };

  const screen = path.startsWith('/login') ? 'login' : path.startsWith('/register') ? 'register' : path.startsWith('/lupa-password') || path === '/ui-preview/lupa-password' ? 'forgot' : path.startsWith('/admin') || path === '/ui-preview/admin' ? 'admin' : path === '/kelas' || path === '/ui-preview/catalog' ? 'catalog' : path.startsWith('/kelas/') ? 'course' : path.startsWith('/checkout/') ? 'checkout' : path.startsWith('/belajar/') ? 'learning' : path.startsWith('/pengaturan') || path === '/ui-preview/settings' ? 'settings' : path.startsWith('/transaksi') || path === '/ui-preview/transactions' ? 'transactions' : 'dashboard';

  if (screen === 'login' || screen === 'register' || screen === 'forgot') {
    return <PreviewGoogleAuth onSubmit={saveUser} onNavigate={go} />;
  }

  if (screen !== 'admin' && !user) {
    go('/login');
    return null;
  }

  const activeCourse = courseFromPath(path);
  return (
    <PlatformShell user={user as User} screen={screen} course={activeCourse} onNavigate={go} onLogout={logout}>
      {screen === 'dashboard' && <DashboardScreen user={user as User} enrollments={enrollments} onNavigate={go} />}
      {screen === 'catalog' && <CatalogScreen enrollments={enrollments} onNavigate={go} />}
      {screen === 'course' && <CourseDetailScreen course={activeCourse} enrolled={enrollments.some((item) => item.courseId === activeCourse.id)} onBack={() => go('/kelas')} onEnroll={() => requestCourse(activeCourse)} />}
      {screen === 'checkout' && <CheckoutScreen course={activeCourse} onBack={() => go('/kelas/' + activeCourse.id)} onComplete={completePayment} />}
      {screen === 'learning' && <LearningScreen course={activeCourse} enrollment={enrollments.find((item) => item.courseId === activeCourse.id)} onBack={() => go('/dashboard')} />}
      {screen === 'settings' && <SettingsScreen user={user as User} onSave={(nextUser) => { writeStorage(STORAGE.user, nextUser); setUser(nextUser); }} />}
      {screen === 'transactions' && <TransactionsScreen enrollments={enrollments} onNavigate={go} />}
    {screen === 'admin' && <AdminScreenV2 enrollments={enrollments} />}
    </PlatformShell>
  );
};

