const CatalogScreen = ({ enrollments, onNavigate }: { enrollments: Enrollment[]; onNavigate: (path: string) => void }) => {
  const [activeTab, setActiveTab] = useState<'all' | 'enrolled'>('all');
  const [query, setQuery] = useState('');
  const [managedCourses] = useState<ManagedCourse[]>(() => readStorage<ManagedCourse[]>(ADMIN_COURSES_STORAGE, defaultManagedCourses()));
  const enrolledIds = new Set(enrollments.map((item) => item.courseId));
  const visibleCourses = useMemo(() => managedCourses.filter((course) => {
    if (!course.published) return false;
    const matchesTab = activeTab === 'all' || enrolledIds.has(course.id);
    const searchText = (course.title + ' ' + course.faculty + ' ' + course.tutor).toLowerCase();
    return matchesTab && searchText.includes(query.toLowerCase().trim());
  }), [activeTab, query, enrollments]);
  return <div className="space-y-5">
    <div className="flex flex-col justify-between gap-3 sm:flex-row sm:items-end"><div><p className="text-xs font-bold uppercase tracking-[0.2em] text-[#006d77]">Program belajar</p><h2 className="mt-2 text-3xl font-semibold tracking-[-0.02em] sm:text-4xl">Katalog kelas</h2><p className="mt-2 max-w-2xl text-sm leading-6 text-[#6a7d71]">Pilih kelas muqarrar sesuai fakultas dan target belajar yang ingin kamu capai.</p></div><button onClick={() => document.getElementById('catalog-search')?.focus()} className="flex min-h-10 items-center gap-2 self-start rounded-xl bg-[#006d77] px-4 text-sm font-bold text-white hover:bg-[#01757f] sm:self-auto"><Search className="h-4 w-4" /> Temukan kelas</button></div>
    <div className="flex flex-col gap-4 border-b border-[#d4e1d8] pb-3 sm:flex-row sm:items-center sm:justify-between"><div className="flex gap-5"><button onClick={() => setActiveTab('all')} className={'border-b-2 px-1 pb-3 text-sm font-bold ' + (activeTab === 'all' ? 'border-[#006d77] text-[#006d77]' : 'border-transparent text-[#819289]')}>Semua kelas <span className="ml-1 text-xs">({managedCourses.length})</span></button><button onClick={() => setActiveTab('enrolled')} className={'border-b-2 px-1 pb-3 text-sm font-bold ' + (activeTab === 'enrolled' ? 'border-[#006d77] text-[#006d77]' : 'border-transparent text-[#819289]')}>Kelas saya <span className="ml-1 text-xs">({enrollments.length})</span></button></div><label className="flex h-10 w-full items-center gap-2 rounded-full border border-[#cbdcd1] bg-white px-3 text-sm text-[#91a399] sm:max-w-[280px]"><Search className="h-4 w-4 shrink-0" /><input id="catalog-search" value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Cari kelas..." className="min-w-0 flex-1 bg-transparent outline-none placeholder:text-[#91a399]" /></label></div>
    {visibleCourses.length ? <div className="grid grid-cols-2 gap-2.5 sm:gap-5 lg:grid-cols-3">{visibleCourses.map((course) => <CatalogCourseCard key={course.id} course={course} enrolled={enrolledIds.has(course.id)} onOpen={() => onNavigate('/kelas/' + course.id)} />)}</div> : <div className="rounded-[20px] border border-dashed border-[#b9d4c4] bg-white p-8 text-center"><Search className="mx-auto h-6 w-6 text-[#006d77]" /><h3 className="mt-4 text-xl font-semibold">Kelas tidak ditemukan</h3><p className="mt-2 text-sm text-[#819289]">Coba gunakan kata kunci lain atau lihat semua program.</p><button onClick={() => { setQuery(''); setActiveTab('all'); }} className="mt-5 text-sm font-bold text-[#006d77]">Reset pencarian</button></div>}
  </div>;
};

const DashboardScreen = ({ user, enrollments, onNavigate }: { user: User; enrollments: Enrollment[]; onNavigate: (path: string) => void }) => {
  const active = enrollments.find((item) => item.status === 'Aktif');
  const course = (active ? courses.find((item) => item.id === active.courseId) : courses[0]) || courses[0];
  const dashboardCourses = (enrollments.length ? enrollments.map((enrollment) => courses.find((item) => item.id === enrollment.courseId) || courses[0]) : courses.slice(0, 3));
  return <div className="space-y-5">
    <div className="flex flex-col justify-between gap-3 sm:flex-row sm:items-end"><div><p className="text-xs font-bold uppercase tracking-[0.2em] text-[#006d77]">Ruang mahasiswa</p><h1 className="mt-2 text-3xl font-semibold tracking-[-0.02em] sm:text-4xl">Assalamu'alaikum, {user.name}</h1><p className="mt-2 text-sm text-[#6a7d71]">Lanjutkan persiapan muqarrar dari tempat terakhir kamu belajar.</p></div><button onClick={() => onNavigate('/kelas')} className="flex min-h-10 items-center gap-2 self-start rounded-full border border-[#bcd3c3] bg-white px-4 text-sm font-bold text-[#006d77] hover:border-[#006d77] sm:self-auto">Jelajahi kelas <ArrowRight className="h-4 w-4" /></button></div>
    <section className="grid gap-4 xl:grid-cols-[minmax(0,1fr)_280px]"><div className="min-w-0 space-y-4"><section className="relative overflow-hidden rounded-[18px] bg-[#006d77] p-6 text-white sm:p-7"><div className="relative z-10 max-w-[570px]"><p className="text-xs font-bold uppercase tracking-[0.2em] text-[#b9ebe0]">Program pilihan Al Madroj</p><h2 className="mt-3 max-w-xl text-3xl font-semibold leading-[1.08] tracking-[-0.02em] sm:text-4xl">Belajar muqarrar lebih siap, satu pertemuan setiap pekan.</h2><p className="mt-3 max-w-lg text-sm leading-6 text-[#d4f2ec]">Akses materi terarah, video pembahasan, dan catatan penting untuk menemani persiapan ujian Al-Azhar.</p><button onClick={() => onNavigate('/belajar/' + course.id)} className="mt-5 flex min-h-10 items-center gap-2 rounded-full bg-white px-4 text-sm font-bold text-[#006d77] hover:bg-[#e9faf5]">{active ? 'Lanjutkan belajar' : 'Lihat program'} <ArrowRight className="h-4 w-4" /></button></div><div className="pointer-events-none absolute -right-8 -top-10 h-52 w-52 rotate-12 border-[22px] border-white/10" /><div className="pointer-events-none absolute -bottom-20 right-20 h-36 w-36 border-[16px] border-[#83c5be]/20" /></section><section className="grid gap-3 sm:grid-cols-3"><DashboardMetric icon={BookOpen} label="Kelas aktif" value={String(enrollments.filter((item) => item.status === 'Aktif').length || 0)} detail="Program terdaftar" /><DashboardMetric icon={CirclePlay} label="Progress belajar" value={active ? '68%' : '0%'} detail="Dari materi tersedia" /><DashboardMetric icon={FileText} label="Muqarrar selesai" value={active ? '14' : '0'} detail="Materi tersimpan" /></section><section><div className="mb-3 flex items-end justify-between gap-4"><div><p className="text-xs font-bold uppercase tracking-[0.18em] text-[#006d77]">Kelas saya</p><h2 className="mt-1 text-xl font-semibold">Lanjutkan belajar</h2></div><button onClick={() => onNavigate('/kelas')} className="flex items-center gap-1 text-sm font-bold text-[#006d77]">Lihat semua <ChevronRight className="h-4 w-4" /></button></div><div className="grid gap-3 md:grid-cols-2 xl:grid-cols-3">{dashboardCourses.map((item, index) => <DashboardCourseCard key={item.id + index} course={item} active={item.id === course.id && Boolean(active)} onOpen={() => onNavigate('/' + (item.id === course.id && active ? 'belajar/' : 'kelas/') + item.id)} />)}</div></section></div><aside className="space-y-4"><section className="rounded-[18px] border border-[#d4e1d8] bg-white p-4"><div className="flex items-start justify-between"><div><p className="text-sm font-semibold">Progress semester</p><p className="mt-1 text-xs text-[#819289]">Target belajar minggu ini</p></div><button aria-label="Opsi progress" title="Opsi progress" className="text-[#819289]"><MoreVertical className="h-4 w-4" /></button></div><div className="mt-4 flex items-center gap-3"><div className="flex h-24 w-24 shrink-0 items-center justify-center rounded-full border-[8px] border-[#dcefe1] text-center"><div><p className="text-xl font-semibold text-[#006d77]">68%</p><p className="text-[10px] font-semibold uppercase tracking-[0.08em] text-[#819289]">tercapai</p></div></div><div><p className="text-sm font-semibold">Tetap konsisten</p><p className="mt-1 text-xs leading-5 text-[#819289]">Selesaikan 2 materi lagi pekan ini.</p></div></div><div className="mt-4 flex h-20 items-end justify-between gap-2 border-b border-[#e2ece5] px-1 pb-2">{[34, 50, 42, 70, 56, 82, 62].map((height, index) => <div key={index} className="flex flex-1 items-end justify-center"><div className={'w-full max-w-5 rounded-t-md ' + (index === 5 ? 'bg-[#006d77]' : 'bg-[#cbe8d3]')} style={{ height: height + '%' }} /></div>)}</div><div className="mt-2 flex justify-between text-[10px] text-[#93a39a]"><span>Sen</span><span>Rab</span><span>Jum</span><span>Min</span></div></section><section className="rounded-[18px] border border-[#d4e1d8] bg-white p-4"><div className="flex items-center justify-between"><h2 className="text-sm font-semibold">Jadwal terdekat</h2><CalendarDays className="h-4 w-4 text-[#006d77]" /></div><div className="mt-3 border-l-2 border-[#8dd0aa] pl-3"><p className="text-xs font-bold uppercase tracking-[0.12em] text-[#006d77]">Rabu · 20.00 WIB</p><p className="mt-1.5 text-sm font-semibold">Kelas live Ushul Fiqh</p><p className="mt-1 text-xs leading-5 text-[#819289]">Pembahasan Mabahits Al-Amr bersama mentor.</p></div><button onClick={() => onNavigate('/belajar/' + course.id)} className="mt-4 flex items-center gap-1 text-sm font-bold text-[#006d77]">Buka ruang belajar <ArrowRight className="h-4 w-4" /></button></section></aside></section>
    <section className="rounded-[22px] border border-[#d4e1d8] bg-white p-5 sm:p-6"><div className="flex items-end justify-between gap-4"><div><p className="text-xs font-bold uppercase tracking-[0.18em] text-[#006d77]">Muqarrar terakhir</p><h2 className="mt-1 text-2xl font-semibold">Materi yang sedang kamu ikuti</h2></div><button onClick={() => onNavigate('/belajar/' + course.id)} className="hidden text-sm font-bold text-[#006d77] sm:block">Lihat ruang belajar</button></div><div className="mt-5 divide-y divide-[#e5eee7]">{['Pengantar muqarrar dan target belajar', 'Mabahits Al-Amr', 'Mabahits An-Nahy'].map((lesson, index) => <button key={lesson} onClick={() => onNavigate('/belajar/' + course.id)} className="flex w-full items-center gap-3 py-3 text-left hover:bg-[#f8fbf8]"><span className="flex h-9 w-9 shrink-0 items-center justify-center rounded-lg bg-[#e8f5ed] text-xs font-bold text-[#006d77]">{String(index + 1).padStart(2, '0')}</span><span className="min-w-0 flex-1"><span className="block truncate text-sm font-semibold">{lesson}</span><span className="mt-1 block text-xs text-[#819289]">{index === 0 ? 'Selesai · Video' : index === 1 ? 'Sedang dipelajari · Video' : 'Berikutnya · Video'}</span></span><ChevronRight className="h-4 w-4 shrink-0 text-[#94a69a]" /></button>)}</div></section>
  </div>;
};

const CourseDetailScreen = ({ course, enrolled, onBack, onEnroll }: { course: Course; enrolled: boolean; onBack: () => void; onEnroll: () => void }) => <div className="space-y-6"><button onClick={onBack} className="flex items-center gap-2 text-sm font-semibold text-[#607568]"><ArrowLeft className="h-4 w-4" /> Kembali ke dashboard</button><section className="grid gap-8 rounded-2xl border border-[#dce9df] bg-white p-6 sm:p-10 lg:grid-cols-[1.15fr_.85fr] lg:items-end"><div><span className="rounded-full bg-[#e4f8ee] px-3 py-1 text-xs font-bold uppercase tracking-[0.12em] text-[#006d77]">{course.faculty}</span><h2 className="mt-6 max-w-3xl text-4xl font-semibold leading-tight sm:text-6xl">{course.title}</h2><p className="mt-5 max-w-2xl text-base leading-7 text-[#607568]">{course.summary}</p><div className="mt-7 flex flex-wrap gap-4 text-sm text-[#607568]"><span className="flex items-center gap-2"><CalendarDays className="h-4 w-4 text-[#006d77]" />{course.schedule}</span><span className="flex items-center gap-2"><BookOpen className="h-4 w-4 text-[#006d77]" />{course.duration}</span><span className="flex items-center gap-2"><UserRound className="h-4 w-4 text-[#006d77]" />{course.tutor}</span></div></div><div className="rounded-xl bg-[#f0faf6] p-6"><p className="text-xs font-bold uppercase tracking-[0.14em] text-[#6e8775]">Investasi belajar</p><p className="mt-2 text-4xl font-semibold text-[#006d77]">{course.price}</p><p className="mt-2 text-sm text-[#607568]">Akses video, PDF muqarrar, dan bank soal.</p><button onClick={onEnroll} disabled={enrolled} className="mt-6 flex min-h-12 w-full items-center justify-center gap-2 rounded-full bg-[#006d77] px-5 text-sm font-bold text-white disabled:cursor-not-allowed disabled:bg-[#88a69b]">{enrolled ? 'Kelas sudah aktif' : 'Daftar kelas'} <ArrowRight className="h-4 w-4" /></button></div></section><section className="grid gap-6 lg:grid-cols-[1fr_.7fr]"><div className="rounded-2xl border border-[#dce9df] bg-white p-6 sm:p-8"><p className="text-xs font-bold uppercase tracking-[0.18em] text-[#006d77]">Materi kelas</p><h3 className="mt-3 text-2xl font-semibold">Yang akan kamu pelajari</h3><div className="mt-6 divide-y divide-[#e4eee7]">{(lessonSets[course.id] || []).map((lesson) => <div key={lesson.title} className="flex items-center justify-between gap-4 py-4"><div className="flex items-center gap-3"><span className="flex h-9 w-9 items-center justify-center rounded-full bg-[#edf8f2] text-[#006d77]">{lesson.type === 'Video' ? <CirclePlay className="h-4 w-4" /> : <FileText className="h-4 w-4" />}</span><span className="text-sm font-semibold">{lesson.title}</span></div><span className="shrink-0 text-xs text-[#799083]">{lesson.duration}</span></div>)}</div></div><div className="rounded-2xl bg-[#102c22] p-6 text-white sm:p-8"><p className="text-xs font-bold uppercase tracking-[0.18em] text-[#83c5be]">Untuk siapa</p><h3 className="mt-3 text-2xl font-semibold">Mahasiswa Al-Azhar yang ingin lebih siap.</h3><p className="mt-4 text-sm leading-6 text-[#c5d9cf]">Materi disusun per bab agar mudah diikuti dari Kairo maupun Indonesia.</p></div></section></div>;

const CheckoutScreen = ({ course, onBack, onComplete }: { course: Course; onBack: () => void; onComplete: (course: Course, payment: PaymentMethod) => void }) => { const [payment, setPayment] = useState<PaymentMethod>('qris'); return <div className="grid gap-6 lg:grid-cols-[1.1fr_.9fr]"><section className="rounded-2xl border border-[#dce9df] bg-white p-6 sm:p-8"><button onClick={onBack} className="flex items-center gap-2 text-sm font-semibold text-[#607568]"><ArrowLeft className="h-4 w-4" /> Kembali ke kelas</button><p className="mt-10 text-xs font-bold uppercase tracking-[0.18em] text-[#006d77]">Ringkasan pendaftaran</p><h2 className="mt-3 text-3xl font-semibold">{course.title}</h2><div className="mt-6 space-y-4 border-t border-[#e1eee4] pt-5 text-sm"><Row label="Peserta" value={readStorage<User | null>(STORAGE.user, null)?.name || 'Peserta Al Madraj'} /><Row label="Jadwal" value={course.schedule} /><Row label="Akses" value="Video, PDF muqarrar, bank soal" /><Row label="Total" value={course.price} strong /></div></section><section className="rounded-2xl bg-[#102c22] p-6 text-white sm:p-8"><p className="text-xs font-bold uppercase tracking-[0.18em] text-[#83c5be]">Pembayaran</p><h2 className="mt-3 text-2xl font-semibold">Pilih metode pembayaran</h2><div className="mt-6 grid gap-3"><PaymentOption active={payment === 'qris'} onClick={() => setPayment('qris')} title="QRIS" text="Scan dari aplikasi pembayaran pilihanmu" /><PaymentOption active={payment === 'va'} onClick={() => setPayment('va')} title="Virtual Account" text="Transfer melalui bank yang tersedia" /></div><p className="mt-5 text-xs leading-5 text-[#b7d0c3]">Preview UI: simulasi alur pembayaran sebelum gateway pembayaran terhubung.</p><button onClick={() => onComplete(course, payment)} className="mt-7 flex min-h-12 w-full items-center justify-center gap-2 rounded-full bg-[#83c5be] px-5 text-sm font-bold text-[#102c22]">Lihat state berhasil <Check className="h-4 w-4" /></button></section></div>; };

const LearningScreen = ({ course, enrollment, onBack }: { course: Course; enrollment?: Enrollment; onBack: () => void }) => {
  const lessons = lessonSets[course.id] || [];
  const [done, setDone] = useState<string[]>(() => readStorage<string[]>(STORAGE.progress + '-' + course.id, []));
  const [activeLesson, setActiveLesson] = useState(0);
  const [activeTab, setActiveTab] = useState<'overview' | 'mentor' | 'faq' | 'announcement'>('overview');
  const [expandedSections, setExpandedSections] = useState<number[]>([0, 1]);
  const [playerOpen, setPlayerOpen] = useState(false);
  const progress = Math.round((done.length / Math.max(lessons.length, 1)) * 100);
  const sections = [{ title: '01: Pengantar Ushul Fiqh', items: lessons.slice(0, 1) }, { title: '02: Mabahits Al-Amr dan An-Nahy', items: lessons.slice(1, 3) }, { title: '03: Ringkasan dan latihan', items: lessons.slice(3) }].filter((section) => section.items.length);
  const instructor = instructorProfiles[course.id] || { initials: 'AM', role: 'Mentor Al Madroj', bio: 'Mentor Al Madroj mendampingi peserta mengikuti muqarrar dengan pembahasan yang runtut dan mudah ditinjau ulang.', focus: 'Pembahasan muqarrar dan persiapan ujian', experience: 'Pengajar program Al Madroj' };
  const toggleDone = (title: string) => { const next = done.includes(title) ? done.filter((item) => item !== title) : [...done, title]; setDone(next); writeStorage(STORAGE.progress + '-' + course.id, next); };
  const selectLesson = (index: number) => setActiveLesson(index);
  return <div className="space-y-5">
    <button onClick={onBack} className="flex items-center gap-2 text-sm font-semibold text-[#607568]"><ArrowLeft className="h-4 w-4" /> Kembali ke dashboard</button>
    <div className="flex flex-col justify-between gap-4 md:flex-row md:items-end"><div><p className="text-xs font-bold uppercase tracking-[0.18em] text-[#006d77]">Ruang belajar / {course.faculty}</p><h1 className="mt-2 max-w-4xl text-3xl font-semibold leading-tight sm:text-5xl">{course.title}</h1><div className="mt-3 flex flex-wrap gap-x-5 gap-y-2 text-xs text-[#71847a]"><span className="flex items-center gap-1.5"><BookOpen className="h-3.5 w-3.5 text-[#006d77]" /> {lessons.length} materi</span><span className="flex items-center gap-1.5"><CirclePlay className="h-3.5 w-3.5 text-[#006d77]" /> Video dan PDF</span><span className="flex items-center gap-1.5"><ShieldCheck className="h-3.5 w-3.5 text-[#006d77]" /> Akses {enrollment?.status === 'Aktif' ? 'aktif' : 'preview'}</span></div></div><div className="flex gap-2"><button className="flex min-h-10 items-center gap-2 rounded-full border border-[#bfd4c5] bg-white px-4 text-sm font-semibold text-[#006d77]"><Bookmark className="h-4 w-4" /> Simpan</button><button className="flex min-h-10 items-center gap-2 rounded-full bg-[#006d77] px-4 text-sm font-bold text-white"><ArrowRight className="h-4 w-4" /> Bagikan</button></div></div>
    <section className="grid gap-5 lg:grid-cols-[minmax(0,1fr)_340px] lg:items-start"><div className="min-w-0 space-y-5"><section className="relative aspect-video overflow-hidden rounded-[20px] bg-[#123d38] p-6 text-white sm:p-10"><div className="absolute right-8 top-8 h-32 w-32 rotate-12 border-[18px] border-[#83c5be]/15 sm:h-48 sm:w-48" /><div className="absolute bottom-8 left-1/3 h-16 w-40 border-y border-[#83c5be]/20" /><div className="relative z-10 flex h-full flex-col justify-between"><div><p className="text-xs font-bold uppercase tracking-[0.2em] text-[#a9e4d5]">Materi {String(activeLesson + 1).padStart(2, '0')}</p><h2 className="mt-3 max-w-xl text-2xl font-semibold leading-tight sm:text-4xl">{lessons[activeLesson]?.title || 'Mulai ruang belajar'}</h2><p className="mt-3 text-sm text-[#c9ebe3]">{course.title}</p></div><div className="flex items-center gap-4"><button onClick={() => setPlayerOpen(true)} aria-label="Putar materi" title="Putar materi" className="flex h-14 w-14 items-center justify-center rounded-full bg-white text-[#006d77] shadow-lg"><CirclePlay className="h-7 w-7 fill-current" /></button><div><p className="text-sm font-semibold">Lanjutkan materi</p><p className="mt-1 text-xs text-[#b6ddd3]">{lessons[activeLesson]?.duration || 'Video pembelajaran'}</p></div></div></div><div className="absolute bottom-0 left-0 h-1.5 bg-[#83c5be] transition-all" style={{ width: Math.max(progress, 6) + '%' }} /></section><nav className="flex gap-5 overflow-x-auto border-b border-[#d4e1d8]" aria-label="Informasi ruang belajar">{([{ key: 'overview', label: 'Overview' }, { key: 'mentor', label: 'Mentor' }, { key: 'faq', label: 'FAQ' }, { key: 'announcement', label: 'Pengumuman' }] as const).map((tab) => <button key={tab.key} onClick={() => setActiveTab(tab.key)} className={'min-h-11 shrink-0 border-b-2 px-1 text-sm font-semibold ' + (activeTab === tab.key ? 'border-[#006d77] text-[#006d77]' : 'border-transparent text-[#819289] hover:text-[#17231b]')}>{tab.label}</button>)}</nav><section className="rounded-[20px] border border-[#d4e1d8] bg-white p-5 sm:p-7">{activeTab === 'overview' && <><p className="text-xs font-bold uppercase tracking-[0.18em] text-[#006d77]">Tentang kelas</p><h2 className="mt-3 text-2xl font-semibold">Peta belajar Ushul Fiqh yang lebih terarah.</h2><p className="mt-4 max-w-3xl text-sm leading-7 text-[#667b70]">Ruang belajar ini menyusun muqarrar menjadi rangkaian pembahasan yang singkat dan mudah diikuti. Tonton video, baca ringkasan, lalu tandai materi yang sudah kamu kuasai.</p><h3 className="mt-7 text-sm font-bold">Yang akan kamu dapatkan</h3><div className="mt-4 grid gap-3 sm:grid-cols-2">{['Penjelasan per bab sesuai muqarrar', 'Video pembahasan bersama mentor', 'Ringkasan istilah penting', 'Progress belajar tersimpan'].map((item) => <p key={item} className="flex items-center gap-2 text-sm text-[#667b70]"><Check className="h-4 w-4 shrink-0 text-[#006d77]" />{item}</p>)}</div></>}{activeTab === 'mentor' && <><div className="flex flex-col gap-5 sm:flex-row sm:items-start"><span className="flex h-16 w-16 shrink-0 items-center justify-center rounded-2xl bg-[#d9eee0] text-xl font-bold text-[#006d77]">{instructor.initials}</span><div><p className="text-xs font-bold uppercase tracking-[0.18em] text-[#006d77]">{instructor.role}</p><h2 className="mt-2 text-2xl font-semibold">{course.tutor}</h2><p className="mt-3 max-w-2xl text-sm leading-7 text-[#667b70]">{instructor.bio}</p></div></div><div className="mt-6 grid gap-3 sm:grid-cols-2"><div className="rounded-xl bg-[#f4faf6] p-4"><p className="text-xs text-[#819289]">Fokus pendampingan</p><p className="mt-1 text-sm font-semibold">{instructor.focus}</p></div><div className="rounded-xl bg-[#f4faf6] p-4"><p className="text-xs text-[#819289]">Profil pengalaman</p><p className="mt-1 text-sm font-semibold">{instructor.experience}</p></div></div></>}{activeTab === 'faq' && <><p className="text-xs font-bold uppercase tracking-[0.18em] text-[#006d77]">Pertanyaan umum</p><h2 className="mt-3 text-2xl font-semibold">Bagaimana cara mengikuti kelas?</h2><p className="mt-4 max-w-2xl text-sm leading-7 text-[#667b70]">Buka materi dari panel di sebelah kanan. Materi yang sudah selesai akan tersimpan sebagai progress akun.</p></>}{activeTab === 'announcement' && <><p className="text-xs font-bold uppercase tracking-[0.18em] text-[#006d77]">Pengumuman</p><h2 className="mt-3 text-2xl font-semibold">Jadwal live berikutnya</h2><p className="mt-4 max-w-2xl text-sm leading-7 text-[#667b70]">Rabu, 20.00 WIB. Siapkan catatan muqarrar dan pertanyaan dari materi yang sedang dipelajari.</p></>}</section></div><aside className="overflow-hidden rounded-[20px] border border-[#d4e1d8] bg-white"><div className="border-b border-[#e2ece5] p-5"><div className="flex items-start justify-between gap-3"><div><h2 className="text-lg font-semibold">Isi kelas</h2><p className="mt-1 text-xs text-[#819289]">{done.length} dari {lessons.length} materi selesai</p></div><span className="text-sm font-bold text-[#006d77]">{progress}%</span></div><div className="mt-4 h-1.5 rounded-full bg-[#e2eee5]"><div className="h-1.5 rounded-full bg-[#006d77] transition-all" style={{ width: progress + '%' }} /></div></div><div className="divide-y divide-[#e2ece5]">{sections.map((section, sectionIndex) => <div key={section.title}><button onClick={() => setExpandedSections((current) => current.includes(sectionIndex) ? current.filter((item) => item !== sectionIndex) : [...current, sectionIndex])} className="flex min-h-12 w-full items-center justify-between gap-3 px-5 text-left text-sm font-semibold"><span>{section.title}</span><ChevronRight className={'h-4 w-4 text-[#819289] transition-transform ' + (expandedSections.includes(sectionIndex) ? 'rotate-90' : '')} /></button>{expandedSections.includes(sectionIndex) && <div className="border-t border-[#eef4ef]">{section.items.map((lesson) => { const index = lessons.findIndex((item) => item.title === lesson.title); const isDone = done.includes(lesson.title); return <div key={lesson.title} className={'flex items-center gap-2 px-5 py-3 ' + (activeLesson === index ? 'bg-[#edf8f1]' : '')}><button onClick={() => selectLesson(index)} className="flex min-w-0 flex-1 items-start gap-3 text-left"><span className={'mt-0.5 flex h-6 w-6 shrink-0 items-center justify-center rounded-full border text-[10px] ' + (isDone ? 'border-[#006d77] bg-[#006d77] text-white' : 'border-[#c9dbcf] text-[#819289]')}>{isDone ? <Check className="h-3 w-3" /> : <CirclePlay className="h-3 w-3" />}</span><span className="min-w-0"><span className={'block text-xs font-semibold leading-5 ' + (isDone ? 'text-[#80938a] line-through' : 'text-[#17231b]')}>{lesson.title}</span><span className="mt-0.5 block text-[10px] text-[#819289]">{lesson.type} · {lesson.duration}</span></span></button><button onClick={() => toggleDone(lesson.title)} aria-label={isDone ? 'Batalkan materi selesai' : 'Tandai materi selesai'} title={isDone ? 'Batalkan selesai' : 'Tandai selesai'} className="flex h-8 w-8 shrink-0 items-center justify-center rounded-full text-[#819289] hover:bg-[#e8f5ed] hover:text-[#006d77]"><Check className={'h-3.5 w-3.5 ' + (isDone ? 'text-[#006d77]' : 'text-[#b7c8bc]')} /></button></div>; })}</div>}</div>)}</div><div className="border-t border-[#e2ece5] p-5"><p className="text-xs font-bold uppercase tracking-[0.16em] text-[#006d77]">Mentor</p><div className="mt-3 flex items-center gap-3"><span className="flex h-10 w-10 items-center justify-center rounded-full bg-[#d9eee0] text-sm font-bold text-[#006d77]">{instructor.initials}</span><div><p className="text-sm font-semibold">{course.tutor}</p><p className="mt-0.5 text-xs text-[#819289]">{instructor.role}</p></div></div></div></aside></section>
    {playerOpen && <Modal title={lessons[activeLesson]?.title || 'Materi pembelajaran'} description="Pemutar materi untuk peserta Al Madroj." onClose={() => setPlayerOpen(false)}><div className="overflow-hidden rounded-2xl bg-[#123d38] p-6 text-white"><div className="flex aspect-video items-center justify-center rounded-xl border border-white/10 bg-[#0d2f2b]"><CirclePlay className="h-12 w-12 text-[#83c5be]" /></div><div className="mt-5 flex flex-col justify-between gap-3 sm:flex-row sm:items-center"><div><p className="text-sm font-semibold">{lessons[activeLesson]?.type || 'Video'} · {lessons[activeLesson]?.duration || 'Siap diputar'}</p><p className="mt-1 text-xs text-[#b6ddd3]">Progress akan tersimpan setelah materi ditandai selesai.</p></div><button onClick={() => { if (lessons[activeLesson]) toggleDone(lessons[activeLesson].title); setPlayerOpen(false); }} className="min-h-10 rounded-full bg-[#83c5be] px-4 text-sm font-bold text-[#123d38]">Tandai selesai</button></div></div></Modal>}
  </div>;
};

const AdminScreenV2 = ({ enrollments }: { enrollments: Enrollment[] }) => {
  type Section = 'overview' | 'classes' | 'materials' | 'participants' | 'access' | 'progress' | 'website';
  type ConfirmState = { title: string; description: string; label: string; action: () => void };
  const [section, setSection] = useState<Section>('overview');
  const [managedCourses, setManagedCourses] = useState<ManagedCourse[]>(() => readStorage<ManagedCourse[]>(ADMIN_COURSES_STORAGE, defaultManagedCourses()));
  const [lessonsByCourse, setLessonsByCourse] = useState<Record<string, Lesson[]>>(() => readStorage<Record<string, Lesson[]>>(ADMIN_LESSONS_STORAGE, lessonSets));
  const [selectedCourseId, setSelectedCourseId] = useState(managedCourses[0]?.id || courses[0].id);
  const [courseDraft, setCourseDraft] = useState<ManagedCourse | null>(null);
  const [lessonDraft, setLessonDraft] = useState<{ title: string; type: Lesson['type']; duration: string } | null>(null);
  const [confirm, setConfirm] = useState<ConfirmState | null>(null);
  const [participant, setParticipant] = useState<Enrollment | null>(null);
  const [accessOverrides, setAccessOverrides] = useState<Record<string, boolean>>(() => readStorage<Record<string, boolean>>(ADMIN_COURSES_STORAGE + '-access', {}));
  const [siteDraft, setSiteDraft] = useState<SiteBlock | null>(null);
  const [notice, setNotice] = useState('');
  const [siteBlocks, setSiteBlocks] = useState<SiteBlock[]>(() => readStorage<SiteBlock[]>(ADMIN_COURSES_STORAGE + '-site', [
    { id: 'hero', label: 'Hero website', description: 'Headline dan ajakan utama di halaman depan.', published: true },
    { id: 'catalog', label: 'Katalog program', description: 'Daftar kelas yang tampil di website utama.', published: true },
    { id: 'facilities', label: 'Fasilitas belajar', description: 'Video, muqarrar, progress, dan pendampingan.', published: true },
    { id: 'faq', label: 'FAQ', description: 'Pertanyaan umum calon peserta.', published: true },
  ]));
  const selectedLessons = lessonsByCourse[selectedCourseId] || [];
  const notify = (message: string) => setNotice(message);
  useEffect(() => { if (!notice) return; const timer = window.setTimeout(() => setNotice(''), 2600); return () => window.clearTimeout(timer); }, [notice]);
  const persistCourses = (next: ManagedCourse[], message = 'Perubahan kelas tersimpan.') => { setManagedCourses(next); writeStorage(ADMIN_COURSES_STORAGE, next); notify(message); };
  const persistLessons = (next: Record<string, Lesson[]>, message = 'Perubahan materi tersimpan.') => { setLessonsByCourse(next); writeStorage(ADMIN_LESSONS_STORAGE, next); notify(message); };
  const blankCourse = (): ManagedCourse => ({ id: 'draft-' + Date.now(), title: '', faculty: 'Syariah', summary: '', tutor: '', schedule: 'Rabu, 20.00 WIB', duration: '12 pertemuan', price: 'Rp199.000', lessons: 0, tone: 'bg-[#e4f8ee]', published: false });
  const saveCourse = (event: React.FormEvent) => { event.preventDefault(); if (!courseDraft?.title.trim()) return; const isDraft = courseDraft.id.startsWith('draft-'); const slug = courseDraft.title.toLowerCase().trim().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '') || 'kelas-baru'; const nextCourse = { ...courseDraft, id: isDraft ? slug : courseDraft.id, lessons: (lessonsByCourse[courseDraft.id] || []).length || courseDraft.lessons }; persistCourses(isDraft ? [...managedCourses, nextCourse] : managedCourses.map((course) => course.id === courseDraft.id ? nextCourse : course)); if (isDraft) persistLessons({ ...lessonsByCourse, [nextCourse.id]: [] }, 'Kelas dan struktur materi dibuat.'); setSelectedCourseId(nextCourse.id); setCourseDraft(null); };
  const deleteCourse = (id: string) => { const next = managedCourses.filter((course) => course.id !== id); const nextLessons = { ...lessonsByCourse }; delete nextLessons[id]; persistCourses(next, 'Kelas dihapus.'); persistLessons(nextLessons, 'Materi kelas ikut dihapus.'); if (selectedCourseId === id) setSelectedCourseId(next[0]?.id || courses[0].id); };
  const toggleCourse = (course: ManagedCourse) => persistCourses(managedCourses.map((item) => item.id === course.id ? { ...item, published: !item.published } : item), course.published ? 'Kelas disimpan sebagai draft.' : 'Kelas dipublikasikan.');
  const saveLesson = (event: React.FormEvent) => { event.preventDefault(); if (!lessonDraft?.title.trim()) return; const nextLessons = { ...lessonsByCourse, [selectedCourseId]: [...selectedLessons, { title: lessonDraft.title.trim(), type: lessonDraft.type, duration: lessonDraft.duration || '12:00' }] }; persistLessons(nextLessons); persistCourses(managedCourses.map((course) => course.id === selectedCourseId ? { ...course, lessons: nextLessons[selectedCourseId].length } : course), 'Jumlah materi diperbarui.'); setLessonDraft(null); };
  const deleteLesson = (title: string) => { const next = { ...lessonsByCourse, [selectedCourseId]: selectedLessons.filter((lesson) => lesson.title !== title) }; persistLessons(next, 'Materi dihapus.'); persistCourses(managedCourses.map((course) => course.id === selectedCourseId ? { ...course, lessons: next[selectedCourseId].length } : course), 'Jumlah materi diperbarui.'); };
  const toggleSiteBlock = (block: SiteBlock) => { const next = siteBlocks.map((item) => item.id === block.id ? { ...item, published: !item.published } : item); setSiteBlocks(next); writeStorage(ADMIN_COURSES_STORAGE + '-site', next); notify(block.published ? 'Blok website dinonaktifkan.' : 'Blok website diaktifkan.'); };
  const toggleAccess = (item: Enrollment) => { const next = { ...accessOverrides, [item.courseId]: !(accessOverrides[item.courseId] ?? true) }; setAccessOverrides(next); writeStorage(ADMIN_COURSES_STORAGE + '-access', next); notify(next[item.courseId] ? 'Akses peserta dipulihkan.' : 'Akses peserta dicabut.'); };
  const saveSiteBlock = (event: React.FormEvent) => { event.preventDefault(); if (!siteDraft?.label.trim()) return; const next = siteBlocks.map((item) => item.id === siteDraft.id ? siteDraft : item); setSiteBlocks(next); writeStorage(ADMIN_COURSES_STORAGE + '-site', next); setSiteDraft(null); notify('Konten website tersimpan.'); };
  const tabs: { id: Section; label: string }[] = [{ id: 'overview', label: 'Ringkasan' }, { id: 'classes', label: 'Kelas' }, { id: 'materials', label: 'Materi' }, { id: 'participants', label: 'Peserta' }, { id: 'access', label: 'Akses' }, { id: 'progress', label: 'Progress' }, { id: 'website', label: 'Website' }];
  return <div className="space-y-5">
    <div className="flex flex-col justify-between gap-3 sm:flex-row sm:items-end"><div><p className="text-xs font-bold uppercase tracking-[0.2em] text-[#006d77]">Workspace pengelola</p><h2 className="mt-2 text-3xl font-semibold sm:text-4xl">Panel admin</h2><p className="mt-2 max-w-2xl text-sm leading-6 text-[#6a7d71]">Kelola kelas, materi, peserta, pembayaran, dan konten publik Al Madroj.</p></div><span className="rounded-full bg-[#e8f5ed] px-3 py-1.5 text-xs font-bold text-[#006d77]">Preview UI · fixture</span></div>
    <nav className="flex gap-5 overflow-x-auto border-b border-[#d4e1d8]" aria-label="Menu panel admin">{tabs.map((tab) => <button key={tab.id} onClick={() => setSection(tab.id)} className={'min-h-11 shrink-0 border-b-2 px-1 text-sm font-semibold ' + (section === tab.id ? 'border-[#006d77] text-[#006d77]' : 'border-transparent text-[#819289] hover:text-[#17231b]')}>{tab.label}</button>)}</nav>
    {section === 'overview' && <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><AdminStat label="Kelas aktif" value={String(managedCourses.filter((course) => course.published).length)} detail="Tampil di katalog" /><AdminStat label="Total materi" value={String(Object.values(lessonsByCourse).reduce((total, lessons) => total + lessons.length, 0))} detail="Video dan PDF" /><AdminStat label="Peserta" value={String(enrollments.length)} detail="Dari fixture browser" /><AdminStat label="Pembayaran aktif" value={String(enrollments.filter((item) => item.status === 'Aktif').length)} detail="Status terkonfirmasi" /></div>}
    {section === 'classes' && <section className="rounded-[18px] border border-[#d4e1d8] bg-white p-5"><div className="flex items-end justify-between gap-4"><div><p className="text-xs font-bold uppercase tracking-[0.18em] text-[#006d77]">Katalog program</p><h3 className="mt-1 text-2xl font-semibold">Atur semua kelas</h3></div><button onClick={() => setCourseDraft(blankCourse())} className="flex min-h-10 items-center gap-2 rounded-full bg-[#006d77] px-4 text-sm font-bold text-white"><Plus className="h-4 w-4" /> Tambah kelas</button></div><div className="mt-5 grid gap-3">{managedCourses.map((course) => <div key={course.id} className="flex flex-col gap-3 rounded-xl border border-[#e0ebe3] p-4 sm:flex-row sm:items-center"><div className={'flex h-14 w-20 shrink-0 items-end rounded-lg p-2 ' + course.tone}><span className="rounded-full bg-white/85 px-2 py-1 text-[9px] font-bold uppercase text-[#006d77]">{course.faculty}</span></div><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><h4 className="font-semibold">{course.title || 'Kelas tanpa judul'}</h4><span className={'rounded-full px-2 py-1 text-[10px] font-bold ' + (course.published ? 'bg-[#e8f5ed] text-[#006d77]' : 'bg-[#f3f5f3] text-[#819289]')}>{course.published ? 'Published' : 'Draft'}</span></div><p className="mt-1 text-xs text-[#819289]">{course.faculty} · {course.lessons} materi · {course.price}</p></div><div className="flex flex-wrap gap-2"><button onClick={() => setConfirm({ title: course.published ? 'Simpan sebagai draft?' : 'Publish kelas?', description: course.published ? 'Kelas tidak akan tampil di katalog peserta.' : 'Kelas akan muncul di katalog peserta.', label: course.published ? 'Unpublish' : 'Publish', action: () => toggleCourse(course) })} className="min-h-9 rounded-full border border-[#cbded0] px-3 text-xs font-semibold text-[#607568]">{course.published ? 'Unpublish' : 'Publish'}</button><button onClick={() => setCourseDraft(course)} aria-label={'Edit ' + course.title} title="Edit kelas" className="flex h-9 w-9 items-center justify-center rounded-full border border-[#cbded0] text-[#006d77]"><Pencil className="h-4 w-4" /></button><button onClick={() => setConfirm({ title: 'Hapus kelas?', description: 'Kelas dan semua materi di dalamnya akan dihapus dari preview.', label: 'Hapus kelas', action: () => deleteCourse(course.id) })} aria-label={'Hapus ' + course.title} title="Hapus kelas" className="flex h-9 w-9 items-center justify-center rounded-full border border-[#efd2c8] text-[#b36d4c]"><Trash2 className="h-4 w-4" /></button></div></div>)}</div></section>}
    {section === 'materials' && <section className="rounded-[18px] border border-[#d4e1d8] bg-white p-5"><div className="flex flex-col justify-between gap-3 sm:flex-row sm:items-end"><div><p className="text-xs font-bold uppercase tracking-[0.18em] text-[#006d77]">Struktur pembelajaran</p><h3 className="mt-1 text-2xl font-semibold">Materi per kelas</h3></div><div className="flex gap-2"><select value={selectedCourseId} onChange={(event) => setSelectedCourseId(event.target.value)} className="min-h-10 min-w-0 rounded-xl border border-[#cbded0] bg-white px-3 text-sm font-semibold outline-none focus:border-[#006d77]">{managedCourses.map((course) => <option key={course.id} value={course.id}>{course.title || 'Kelas tanpa judul'}</option>)}</select><button onClick={() => setLessonDraft({ title: '', type: 'Video', duration: '12:00' })} className="flex min-h-10 shrink-0 items-center gap-2 rounded-full bg-[#006d77] px-3 text-sm font-bold text-white"><Plus className="h-4 w-4" /> Materi</button></div></div><div className="mt-5 divide-y divide-[#e4eee7]">{selectedLessons.length ? selectedLessons.map((lesson, index) => <div key={lesson.title} className="flex items-center gap-3 py-3"><span className="flex h-8 w-8 shrink-0 items-center justify-center rounded-lg bg-[#e8f5ed] text-xs font-bold text-[#006d77]">{String(index + 1).padStart(2, '0')}</span><div className="min-w-0 flex-1"><p className="text-sm font-semibold">{lesson.title}</p><p className="mt-1 text-xs text-[#819289]">{lesson.type} · {lesson.duration}</p></div><button onClick={() => setConfirm({ title: 'Hapus materi?', description: 'Materi ini akan dihapus dari struktur kelas.', label: 'Hapus materi', action: () => deleteLesson(lesson.title) })} aria-label={'Hapus ' + lesson.title} title="Hapus materi" className="flex h-8 w-8 items-center justify-center rounded-full text-[#b36d4c] hover:bg-[#fff3ef]"><Trash2 className="h-4 w-4" /></button></div>) : <p className="rounded-xl bg-[#f7faf8] p-5 text-sm text-[#819289]">Belum ada materi di kelas ini.</p>}</div></section>}
    {section === 'participants' && <section className="rounded-[18px] border border-[#d4e1d8] bg-white p-5"><div><p className="text-xs font-bold uppercase tracking-[0.18em] text-[#006d77]">Data pendaftar</p><h3 className="mt-1 text-2xl font-semibold">Peserta dan pembayaran</h3></div>{enrollments.length ? <div className="mt-5 overflow-x-auto"><table className="w-full min-w-[650px] text-left text-sm"><thead className="border-b border-[#e1eee4] text-xs uppercase tracking-[0.12em] text-[#799083]"><tr><th className="pb-3 font-semibold">Peserta</th><th className="pb-3 font-semibold">Program</th><th className="pb-3 font-semibold">Status</th><th className="pb-3 font-semibold">Aksi</th></tr></thead><tbody className="divide-y divide-[#e1eee4]">{enrollments.map((item) => <tr key={item.courseId}><td className="py-3 font-semibold">Demo Peserta</td><td className="py-3">{courses.find((course) => course.id === item.courseId)?.title}</td><td className="py-3"><span className="rounded-full bg-[#e4f8ee] px-2.5 py-1 text-xs font-semibold text-[#006d77]">{item.status}</span></td><td className="py-3"><button onClick={() => setParticipant(item)} className="text-xs font-bold text-[#006d77]">Lihat detail</button></td></tr>)}</tbody></table></div> : <p className="mt-5 rounded-xl bg-[#f7faf8] p-5 text-sm text-[#819289]">Belum ada pendaftaran dari browser ini.</p>}</section>}
    {section === 'access' && <section className="rounded-[18px] border border-[#d4e1d8] bg-white p-5"><div><p className="text-xs font-bold uppercase tracking-[0.18em] text-[#006d77]">Kontrol akses</p><h3 className="mt-1 text-2xl font-semibold">Akses kelas peserta</h3><p className="mt-2 text-sm leading-6 text-[#819289]">Berikan atau cabut akses secara manual untuk kebutuhan operasional.</p></div>{enrollments.length ? <div className="mt-5 divide-y divide-[#e4eee7]">{enrollments.map((item) => { const course = courses.find((entry) => entry.id === item.courseId) || courses[0]; const active = accessOverrides[item.courseId] ?? true; return <div key={item.courseId} className="flex flex-col gap-3 py-4 sm:flex-row sm:items-center"><div className="flex min-w-0 flex-1 items-center gap-3"><span className={'flex h-10 w-10 shrink-0 items-center justify-center rounded-xl ' + (active ? 'bg-[#e8f5ed] text-[#006d77]' : 'bg-[#fff3ef] text-[#b36d4c]')}><ShieldCheck className="h-5 w-5" /></span><div className="min-w-0"><p className="truncate text-sm font-semibold">Demo Peserta</p><p className="mt-1 truncate text-xs text-[#819289]">{course.title}</p></div></div><span className={'w-fit rounded-full px-2.5 py-1 text-xs font-bold ' + (active ? 'bg-[#e8f5ed] text-[#006d77]' : 'bg-[#fff3ef] text-[#b36d4c]')}>{active ? 'Akses aktif' : 'Akses dicabut'}</span><button onClick={() => toggleAccess(item)} className={'min-h-9 rounded-full px-3 text-xs font-bold ' + (active ? 'border border-[#efd2c8] text-[#b36d4c]' : 'bg-[#006d77] text-white')}>{active ? 'Cabut akses' : 'Pulihkan akses'}</button></div>; })}</div> : <p className="mt-5 rounded-xl bg-[#f7faf8] p-5 text-sm text-[#819289]">Belum ada peserta untuk diatur.</p>}</section>}
    {section === 'progress' && <section className="rounded-[18px] border border-[#d4e1d8] bg-white p-5"><div><p className="text-xs font-bold uppercase tracking-[0.18em] text-[#006d77]">Monitoring belajar</p><h3 className="mt-1 text-2xl font-semibold">Progress peserta</h3><p className="mt-2 text-sm leading-6 text-[#819289]">Ringkasan materi selesai untuk membantu follow-up mentor.</p></div>{enrollments.length ? <div className="mt-5 divide-y divide-[#e4eee7]">{enrollments.map((item) => { const course = courses.find((entry) => entry.id === item.courseId) || courses[0]; const lessonList = lessonSets[item.courseId] || []; const completed = readStorage<string[]>(STORAGE.progress + '-' + item.courseId, []); const percentage = Math.round((completed.length / Math.max(lessonList.length, 1)) * 100); return <div key={item.courseId} className="py-4"><div className="flex items-center justify-between gap-4"><div><p className="text-sm font-semibold">Demo Peserta</p><p className="mt-1 text-xs text-[#819289]">{course.title}</p></div><span className="text-sm font-bold text-[#006d77]">{percentage}%</span></div><div className="mt-3 h-2 rounded-full bg-[#e3eee6]"><div className="h-2 rounded-full bg-[#006d77]" style={{ width: percentage + '%' }} /></div><div className="mt-2 flex justify-between text-[11px] text-[#819289]"><span>{completed.length} dari {lessonList.length} materi selesai</span><span>{percentage >= 100 ? 'Selesai' : percentage ? 'Sedang berjalan' : 'Belum mulai'}</span></div></div>; })}</div> : <p className="mt-5 rounded-xl bg-[#f7faf8] p-5 text-sm text-[#819289]">Belum ada progress peserta.</p>}</section>}
    {section === 'website' && <section className="rounded-[18px] border border-[#d4e1d8] bg-white p-5"><div><p className="text-xs font-bold uppercase tracking-[0.18em] text-[#006d77]">Konten publik</p><h3 className="mt-1 text-2xl font-semibold">Bagian website utama</h3></div><div className="mt-5 divide-y divide-[#e4eee7]">{siteBlocks.map((block) => <div key={block.id} className="flex flex-col gap-3 py-4 sm:flex-row sm:items-center"><span className={'flex h-8 w-8 shrink-0 items-center justify-center rounded-lg text-[10px] font-bold ' + (block.published ? 'bg-[#e8f5ed] text-[#006d77]' : 'bg-[#f1f4f1] text-[#819289]')}>{block.published ? 'ON' : 'OFF'}</span><div className="min-w-0 flex-1"><p className="text-sm font-semibold">{block.label}</p><p className="mt-1 text-xs text-[#819289]">{block.description}</p></div><div className="flex gap-2"><button onClick={() => setSiteDraft(block)} aria-label={'Edit ' + block.label} title="Edit konten" className="flex h-9 w-9 items-center justify-center rounded-full border border-[#cbded0] text-[#006d77]"><Pencil className="h-4 w-4" /></button><button onClick={() => toggleSiteBlock(block)} className={'min-h-9 rounded-full px-3 text-xs font-bold ' + (block.published ? 'border border-[#c5dacf] text-[#006d77]' : 'bg-[#006d77] text-white')}>{block.published ? 'Nonaktifkan' : 'Aktifkan'}</button></div></div>)}</div></section>}
    {courseDraft && <Modal title={courseDraft.id.startsWith('draft-') ? 'Tambah kelas' : 'Edit kelas'} description="Lengkapi informasi yang tampil di katalog peserta." onClose={() => setCourseDraft(null)}><form onSubmit={saveCourse} className="space-y-4"><div className="grid gap-4 sm:grid-cols-2"><AdminField label="Nama kelas" value={courseDraft.title} onChange={(value) => setCourseDraft({ ...courseDraft, title: value })} placeholder="Ushul Fiqh Dasar" /><AdminField label="Fakultas" value={courseDraft.faculty} onChange={(value) => setCourseDraft({ ...courseDraft, faculty: value })} placeholder="Syariah" /><AdminField label="Mentor" value={courseDraft.tutor} onChange={(value) => setCourseDraft({ ...courseDraft, tutor: value })} placeholder="Nama mentor" /><AdminField label="Harga" value={courseDraft.price} onChange={(value) => setCourseDraft({ ...courseDraft, price: value })} placeholder="Rp199.000" /><AdminField label="Jadwal" value={courseDraft.schedule} onChange={(value) => setCourseDraft({ ...courseDraft, schedule: value })} placeholder="Rabu, 20.00 WIB" /><AdminField label="Durasi" value={courseDraft.duration} onChange={(value) => setCourseDraft({ ...courseDraft, duration: value })} placeholder="12 pertemuan" /></div><label className="block"><span className="mb-2 block text-sm font-semibold">Deskripsi kelas</span><textarea value={courseDraft.summary} onChange={(event) => setCourseDraft({ ...courseDraft, summary: event.target.value })} rows={3} className="w-full rounded-xl border border-[#cbded0] px-4 py-3 text-sm outline-none focus:border-[#006d77]" placeholder="Fokus dan hasil belajar kelas." /></label><div className="flex justify-end gap-2"><button type="button" onClick={() => setCourseDraft(null)} className="min-h-10 rounded-full border border-[#cbded0] px-4 text-sm font-semibold text-[#607568]">Batal</button><button type="submit" className="flex min-h-10 items-center gap-2 rounded-full bg-[#006d77] px-4 text-sm font-bold text-white"><Save className="h-4 w-4" /> Simpan kelas</button></div></form></Modal>}
    {lessonDraft && <Modal title="Tambah materi" description="Tambahkan video atau PDF ke kelas yang sedang dipilih." onClose={() => setLessonDraft(null)}><form onSubmit={saveLesson} className="space-y-4"><AdminField label="Judul materi" value={lessonDraft.title} onChange={(value) => setLessonDraft({ ...lessonDraft, title: value })} placeholder="Mabahits Al-Amr" /><div className="grid gap-4 sm:grid-cols-2"><label className="block"><span className="mb-2 block text-sm font-semibold">Tipe materi</span><select value={lessonDraft.type} onChange={(event) => setLessonDraft({ ...lessonDraft, type: event.target.value as Lesson['type'] })} className="min-h-11 w-full rounded-xl border border-[#cbded0] bg-white px-3 text-sm outline-none focus:border-[#006d77]"><option>Video</option><option>PDF</option></select></label><AdminField label="Durasi" value={lessonDraft.duration} onChange={(value) => setLessonDraft({ ...lessonDraft, duration: value })} placeholder="12:00" /></div><div className="flex justify-end gap-2"><button type="button" onClick={() => setLessonDraft(null)} className="min-h-10 rounded-full border border-[#cbded0] px-4 text-sm font-semibold text-[#607568]">Batal</button><button type="submit" className="flex min-h-10 items-center gap-2 rounded-full bg-[#006d77] px-4 text-sm font-bold text-white"><Save className="h-4 w-4" /> Simpan materi</button></div></form></Modal>}
    {confirm && <Modal title={confirm.title} description={confirm.description} onClose={() => setConfirm(null)}><div className="flex justify-end gap-2"><button onClick={() => setConfirm(null)} className="min-h-10 rounded-full border border-[#cbded0] px-4 text-sm font-semibold text-[#607568]">Batal</button><button onClick={() => { confirm.action(); setConfirm(null); }} className="min-h-10 rounded-full bg-[#b36d4c] px-4 text-sm font-bold text-white">{confirm.label}</button></div></Modal>}
    {participant && <Modal title="Detail peserta" description="Ringkasan enrollment dari data preview." onClose={() => setParticipant(null)}><div className="space-y-3 text-sm"><Row label="Peserta" value="Demo Peserta" /><Row label="Program" value={courses.find((course) => course.id === participant.courseId)?.title || '-'} /><Row label="Status" value={participant.status} /><Row label="Metode" value={participant.payment.toUpperCase()} /><Row label="Tanggal" value={new Date(participant.createdAt).toLocaleDateString('id-ID')} /></div><button onClick={() => setParticipant(null)} className="mt-5 flex min-h-10 w-full items-center justify-center rounded-full bg-[#006d77] text-sm font-bold text-white">Tutup</button></Modal>}
    {siteDraft && <Modal title="Edit konten website" description="Perubahan ini mengatur label dan deskripsi blok pada website publik." onClose={() => setSiteDraft(null)}><form onSubmit={saveSiteBlock} className="space-y-4"><AdminField label="Nama blok" value={siteDraft.label} onChange={(value) => setSiteDraft({ ...siteDraft, label: value })} placeholder="Hero website" /><label className="block"><span className="mb-2 block text-sm font-semibold">Deskripsi</span><textarea value={siteDraft.description} onChange={(event) => setSiteDraft({ ...siteDraft, description: event.target.value })} rows={4} className="w-full rounded-xl border border-[#cbded0] px-4 py-3 text-sm outline-none focus:border-[#006d77]" /></label><div className="flex justify-end gap-2"><button type="button" onClick={() => setSiteDraft(null)} className="min-h-10 rounded-full border border-[#cbded0] px-4 text-sm font-semibold text-[#607568]">Batal</button><button type="submit" className="flex min-h-10 items-center gap-2 rounded-full bg-[#006d77] px-4 text-sm font-bold text-white"><Save className="h-4 w-4" /> Simpan konten</button></div></form></Modal>}
    {notice && <Toast message={notice} />}
  </div>;
};

const AdminScreen = ({ enrollments }: { enrollments: Enrollment[] }) => {
  type AdminSection = 'overview' | 'classes' | 'materials' | 'participants' | 'website';
  const [section, setSection] = useState<AdminSection>('overview');
  const [confirmAction, setConfirmAction] = useState<{ title: string; description: string; confirmLabel: string; onConfirm: () => void } | null>(null);
  const [selectedParticipant, setSelectedParticipant] = useState<Enrollment | null>(null);
  const [notice, setNotice] = useState('');
  const [managedCourses, setManagedCourses] = useState<ManagedCourse[]>(() => readStorage<ManagedCourse[]>(ADMIN_COURSES_STORAGE, defaultManagedCourses()));
  const [editingCourse, setEditingCourse] = useState<ManagedCourse | null>(null);
  const [lessonsByCourse, setLessonsByCourse] = useState<Record<string, Lesson[]>>(() => readStorage<Record<string, Lesson[]>>(ADMIN_LESSONS_STORAGE, lessonSets));
  const [selectedCourseId, setSelectedCourseId] = useState(managedCourses[0]?.id || courses[0].id);
  const [newLessonTitle, setNewLessonTitle] = useState('');
  const [siteBlocks, setSiteBlocks] = useState<SiteBlock[]>(() => readStorage<SiteBlock[]>(ADMIN_COURSES_STORAGE + '-site', [
    { id: 'hero', label: 'Hero website', description: 'Headline dan ajakan utama di halaman depan.', published: true },
    { id: 'catalog', label: 'Katalog program', description: 'Daftar kelas yang tampil di website utama.', published: true },
    { id: 'facilities', label: 'Fasilitas belajar', description: 'Video, muqarrar, progress, dan pendampingan.', published: true },
    { id: 'faq', label: 'FAQ', description: 'Pertanyaan umum calon peserta.', published: true },
  ]));
  const selectedLessons = lessonsByCourse[selectedCourseId] || [];
  const saveCourses = (next: ManagedCourse[]) => { setManagedCourses(next); writeStorage(ADMIN_COURSES_STORAGE, next); setNotice('Perubahan kelas tersimpan.'); };
  const saveLessons = (next: Record<string, Lesson[]>) => { setLessonsByCourse(next); writeStorage(ADMIN_LESSONS_STORAGE, next); setNotice('Perubahan materi tersimpan.'); };
  const startNewCourse = () => setEditingCourse({ id: 'draft-' + Date.now(), title: '', faculty: 'Syariah', summary: '', tutor: '', schedule: 'Rabu, 20.00 WIB', duration: '12 pertemuan', price: 'Rp0', lessons: 0, tone: 'bg-[#e4f8ee]', published: false });
  const saveCourse = (event: React.FormEvent) => { event.preventDefault(); if (!editingCourse?.title.trim()) return; const isDraft = editingCourse.id.startsWith('draft-'); const slug = editingCourse.title.toLowerCase().trim().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '') || 'kelas-baru'; const nextCourse = { ...editingCourse, id: isDraft ? slug : editingCourse.id, lessons: (lessonsByCourse[editingCourse.id] || []).length || editingCourse.lessons }; saveCourses(isDraft ? [...managedCourses, nextCourse] : managedCourses.map((course) => course.id === editingCourse.id ? nextCourse : editingCourse.id === nextCourse.id ? nextCourse : course)); if (isDraft && !lessonsByCourse[nextCourse.id]) saveLessons({ ...lessonsByCourse, [nextCourse.id]: [] }); setSelectedCourseId(nextCourse.id); setEditingCourse(null); };
  const togglePublished = (id: string) => saveCourses(managedCourses.map((course) => course.id === id ? { ...course, published: !course.published } : course));
  const deleteCourse = (id: string) => { saveCourses(managedCourses.filter((course) => course.id !== id)); const nextLessons = { ...lessonsByCourse }; delete nextLessons[id]; saveLessons(nextLessons); if (selectedCourseId === id) setSelectedCourseId(managedCourses.find((course) => course.id !== id)?.id || courses[0].id); };
  const addLesson = (event: React.FormEvent) => { event.preventDefault(); if (!newLessonTitle.trim()) return; const next = { ...lessonsByCourse, [selectedCourseId]: [...selectedLessons, { title: newLessonTitle.trim(), type: 'Video' as const, duration: '12:00' }] }; saveLessons(next); saveCourses(managedCourses.map((course) => course.id === selectedCourseId ? { ...course, lessons: next[selectedCourseId].length } : course)); setNewLessonTitle(''); };
  const removeLesson = (title: string) => { const next = { ...lessonsByCourse, [selectedCourseId]: selectedLessons.filter((lesson) => lesson.title !== title) }; saveLessons(next); saveCourses(managedCourses.map((course) => course.id === selectedCourseId ? { ...course, lessons: next[selectedCourseId].length } : course)); };
  const updateSiteBlock = (id: string, patch: Partial<SiteBlock>) => { const next = siteBlocks.map((block) => block.id === id ? { ...block, ...patch } : block); setSiteBlocks(next); writeStorage(ADMIN_COURSES_STORAGE + '-site', next); setNotice('Konten website diperbarui.'); };
  useEffect(() => { if (!notice) return; const timer = window.setTimeout(() => setNotice(''), 2600); return () => window.clearTimeout(timer); }, [notice]);
  const tabs: { id: AdminSection; label: string }[] = [{ id: 'overview', label: 'Ringkasan' }, { id: 'classes', label: 'Kelas' }, { id: 'materials', label: 'Materi' }, { id: 'participants', label: 'Peserta' }, { id: 'website', label: 'Website' }];
  return <div className="space-y-6">
    <div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p className="text-xs font-bold uppercase tracking-[0.2em] text-[#006d77]">Workspace pengelola</p><h2 className="mt-2 text-3xl font-semibold tracking-[-0.02em] sm:text-5xl">Panel admin</h2><p className="mt-3 max-w-2xl text-sm leading-6 text-[#6a7d71]">Atur program belajar, materi, peserta, dan konten yang tampil di website Al Madroj.</p></div><span className="rounded-full bg-[#e8f5ed] px-3 py-1.5 text-xs font-bold text-[#006d77]">Preview UI · fixture</span></div>
    <nav className="flex gap-5 overflow-x-auto border-b border-[#d4e1d8]" aria-label="Menu panel admin">{tabs.map((tab) => <button key={tab.id} onClick={() => setSection(tab.id)} className={'min-h-12 shrink-0 border-b-2 px-1 text-sm font-semibold ' + (section === tab.id ? 'border-[#006d77] text-[#006d77]' : 'border-transparent text-[#819289] hover:text-[#17231b]')}>{tab.label}</button>)}</nav>
    {section === 'overview' && <div className="space-y-6"><section className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><AdminStat label="Kelas aktif" value={String(managedCourses.filter((course) => course.published).length)} detail="Tampil di katalog" /><AdminStat label="Total materi" value={String(Object.values(lessonsByCourse).reduce((total, lessons) => total + lessons.length, 0))} detail="Video dan PDF" /><AdminStat label="Peserta" value={String(enrollments.length)} detail="Dari fixture browser" /><AdminStat label="Pembayaran aktif" value={String(enrollments.filter((item) => item.status === 'Aktif').length)} detail="Status terkonfirmasi" /></section><section className="grid gap-5 lg:grid-cols-[1.2fr_.8fr]"><div className="rounded-[20px] border border-[#d4e1d8] bg-white p-6"><div className="flex items-end justify-between gap-4"><div><p className="text-xs font-bold uppercase tracking-[0.18em] text-[#006d77]">Aksi cepat</p><h3 className="mt-2 text-2xl font-semibold">Kelola konten utama</h3></div><Settings className="h-5 w-5 text-[#006d77]" /></div><div className="mt-5 grid gap-3 sm:grid-cols-2"><AdminQuickAction title="Tambah kelas baru" text="Buat program dan atur harga." onClick={() => { setSection('classes'); startNewCourse(); }} /><AdminQuickAction title="Atur materi" text="Susun video dan PDF per kelas." onClick={() => setSection('materials')} /><AdminQuickAction title="Lihat peserta" text="Pantau status pendaftaran." onClick={() => setSection('participants')} /><AdminQuickAction title="Konten website" text="Atur blok yang tampil publik." onClick={() => setSection('website')} /></div></div><div className="rounded-[20px] bg-[#123d38] p-6 text-white"><p className="text-xs font-bold uppercase tracking-[0.18em] text-[#a9e4d5]">Status platform</p><h3 className="mt-3 text-2xl font-semibold">Semua bagian siap diatur.</h3><p className="mt-3 text-sm leading-6 text-[#c9ebe3]">Setiap perubahan di preview tersimpan di browser dan nantinya dipetakan ke tabel Supabase.</p><button onClick={() => setSection('classes')} className="mt-6 flex min-h-10 items-center gap-2 rounded-full bg-white px-4 text-sm font-bold text-[#006d77]">Buka manajemen kelas <ArrowRight className="h-4 w-4" /></button></div></section></div>}
    {section === 'classes' && <div className="space-y-5">{editingCourse && <form onSubmit={saveCourse} className="rounded-[20px] border border-[#bcd8c4] bg-[#f3faf5] p-5 sm:p-7"><div className="flex items-start justify-between gap-4"><div><p className="text-xs font-bold uppercase tracking-[0.18em] text-[#006d77]">{editingCourse.id.startsWith('draft-') ? 'Kelas baru' : 'Edit kelas'}</p><h3 className="mt-2 text-2xl font-semibold">Detail program</h3></div><button type="button" onClick={() => setEditingCourse(null)} aria-label="Tutup form" title="Tutup form" className="flex h-9 w-9 items-center justify-center rounded-full border border-[#c5dacf] text-[#607568]"><X className="h-4 w-4" /></button></div><div className="mt-5 grid gap-4 md:grid-cols-2"><AdminField label="Nama kelas" value={editingCourse.title} onChange={(value) => setEditingCourse({ ...editingCourse, title: value })} placeholder="Contoh: Ushul Fiqh Dasar" /><AdminField label="Fakultas" value={editingCourse.faculty} onChange={(value) => setEditingCourse({ ...editingCourse, faculty: value })} placeholder="Syariah" /><AdminField label="Mentor" value={editingCourse.tutor} onChange={(value) => setEditingCourse({ ...editingCourse, tutor: value })} placeholder="Nama mentor" /><AdminField label="Harga" value={editingCourse.price} onChange={(value) => setEditingCourse({ ...editingCourse, price: value })} placeholder="Rp199.000" /><AdminField label="Jadwal" value={editingCourse.schedule} onChange={(value) => setEditingCourse({ ...editingCourse, schedule: value })} placeholder="Rabu, 20.00 WIB" /><AdminField label="Durasi" value={editingCourse.duration} onChange={(value) => setEditingCourse({ ...editingCourse, duration: value })} placeholder="12 pertemuan" /></div><label className="mt-4 block"><span className="mb-2 block text-sm font-semibold">Deskripsi kelas</span><textarea value={editingCourse.summary} onChange={(event) => setEditingCourse({ ...editingCourse, summary: event.target.value })} rows={3} className="w-full rounded-xl border border-[#cbded0] bg-white px-4 py-3 text-sm outline-none focus:border-[#006d77]" placeholder="Jelaskan fokus program dan hasil belajar." /></label><div className="mt-5 flex flex-wrap justify-end gap-3"><button type="button" onClick={() => setEditingCourse(null)} className="min-h-10 rounded-full border border-[#c5dacf] px-4 text-sm font-semibold text-[#607568]">Batal</button><button type="submit" className="flex min-h-10 items-center gap-2 rounded-full bg-[#006d77] px-4 text-sm font-bold text-white"><Save className="h-4 w-4" /> Simpan kelas</button></div></form>}<section className="rounded-[20px] border border-[#d4e1d8] bg-white p-5 sm:p-7"><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p className="text-xs font-bold uppercase tracking-[0.18em] text-[#006d77]">Katalog program</p><h3 className="mt-2 text-2xl font-semibold">Semua kelas</h3></div><button onClick={startNewCourse} className="flex min-h-10 items-center gap-2 self-start rounded-full bg-[#006d77] px-4 text-sm font-bold text-white"><Plus className="h-4 w-4" /> Tambah kelas</button></div><div className="mt-6 grid gap-3">{managedCourses.map((course) => <div key={course.id} className="flex flex-col gap-4 rounded-2xl border border-[#e0ebe3] p-4 sm:flex-row sm:items-center"><div className={'flex h-16 w-20 shrink-0 items-end rounded-xl p-2 ' + course.tone}><span className="rounded-full bg-white/85 px-2 py-1 text-[9px] font-bold uppercase text-[#006d77]">{course.faculty}</span></div><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><h4 className="font-semibold">{course.title || 'Kelas tanpa judul'}</h4><span className={'rounded-full px-2 py-1 text-[10px] font-bold ' + (course.published ? 'bg-[#e8f5ed] text-[#006d77]' : 'bg-[#f3f5f3] text-[#819289]')}>{course.published ? 'Published' : 'Draft'}</span></div><p className="mt-1 text-xs text-[#819289]">{course.faculty} · {course.lessons} materi · {course.price}</p></div><div className="flex flex-wrap gap-2"><button onClick={() => togglePublished(course.id)} className="min-h-9 rounded-full border border-[#cbded0] px-3 text-xs font-semibold text-[#607568]">{course.published ? 'Unpublish' : 'Publish'}</button><button onClick={() => setEditingCourse(course)} aria-label={'Edit ' + course.title} title="Edit kelas" className="flex h-9 w-9 items-center justify-center rounded-full border border-[#cbded0] text-[#006d77]"><Pencil className="h-4 w-4" /></button><button onClick={() => deleteCourse(course.id)} aria-label={'Hapus ' + course.title} title="Hapus kelas" className="flex h-9 w-9 items-center justify-center rounded-full border border-[#efd2c8] text-[#b36d4c]"><Trash2 className="h-4 w-4" /></button></div></div>)}</div></section></div>}
    {section === 'materials' && <section className="rounded-[20px] border border-[#d4e1d8] bg-white p-5 sm:p-7"><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p className="text-xs font-bold uppercase tracking-[0.18em] text-[#006d77]">Struktur pembelajaran</p><h3 className="mt-2 text-2xl font-semibold">Materi per kelas</h3></div><select value={selectedCourseId} onChange={(event) => setSelectedCourseId(event.target.value)} className="min-h-10 rounded-xl border border-[#cbded0] bg-white px-3 text-sm font-semibold outline-none focus:border-[#006d77]">{managedCourses.map((course) => <option key={course.id} value={course.id}>{course.title || 'Kelas tanpa judul'}</option>)}</select></div><form onSubmit={addLesson} className="mt-6 flex flex-col gap-3 sm:flex-row"><input value={newLessonTitle} onChange={(event) => setNewLessonTitle(event.target.value)} placeholder="Judul materi baru" className="min-h-11 flex-1 rounded-xl border border-[#cbded0] px-4 text-sm outline-none focus:border-[#006d77]" /><button className="flex min-h-11 items-center justify-center gap-2 rounded-xl bg-[#006d77] px-4 text-sm font-bold text-white"><Plus className="h-4 w-4" /> Tambah materi</button></form><div className="mt-6 divide-y divide-[#e4eee7]">{selectedLessons.length ? selectedLessons.map((lesson, index) => <div key={lesson.title} className="flex items-center gap-4 py-4"><span className="flex h-9 w-9 shrink-0 items-center justify-center rounded-lg bg-[#e8f5ed] text-xs font-bold text-[#006d77]">{String(index + 1).padStart(2, '0')}</span><div className="min-w-0 flex-1"><p className="text-sm font-semibold">{lesson.title}</p><p className="mt-1 text-xs text-[#819289]">{lesson.type} · {lesson.duration}</p></div><button onClick={() => removeLesson(lesson.title)} aria-label={'Hapus ' + lesson.title} title="Hapus materi" className="flex h-9 w-9 items-center justify-center rounded-full text-[#b36d4c] hover:bg-[#fff3ef]"><Trash2 className="h-4 w-4" /></button></div>) : <p className="rounded-xl bg-[#f7faf8] p-5 text-sm text-[#819289]">Belum ada materi di kelas ini.</p>}</div></section>}
    {section === 'participants' && <section className="rounded-[20px] border border-[#d4e1d8] bg-white p-5 sm:p-7"><div><p className="text-xs font-bold uppercase tracking-[0.18em] text-[#006d77]">Data pendaftar</p><h3 className="mt-2 text-2xl font-semibold">Peserta dan pembayaran</h3></div>{enrollments.length ? <div className="mt-6 overflow-x-auto"><table className="w-full min-w-[680px] text-left text-sm"><thead className="border-b border-[#e1eee4] text-xs uppercase tracking-[0.12em] text-[#799083]"><tr><th className="pb-3 font-semibold">Peserta</th><th className="pb-3 font-semibold">Program</th><th className="pb-3 font-semibold">Status</th><th className="pb-3 font-semibold">Metode</th><th className="pb-3 font-semibold">Tanggal</th></tr></thead><tbody className="divide-y divide-[#e1eee4]">{enrollments.map((item) => <tr key={item.courseId}><td className="py-4 font-semibold">Demo Peserta</td><td className="py-4">{courses.find((course) => course.id === item.courseId)?.title}</td><td className="py-4"><span className="rounded-full bg-[#e4f8ee] px-2.5 py-1 text-xs font-semibold text-[#006d77]">{item.status}</span></td><td className="py-4 uppercase text-[#607568]">{item.payment}</td><td className="py-4 text-[#607568]">{new Date(item.createdAt).toLocaleDateString('id-ID')}</td></tr>)}</tbody></table></div> : <p className="mt-6 rounded-xl bg-[#f7faf8] p-5 text-sm text-[#819289]">Belum ada pendaftaran dari browser ini.</p>}</section>}
    {section === 'website' && <section className="rounded-[20px] border border-[#d4e1d8] bg-white p-5 sm:p-7"><div><p className="text-xs font-bold uppercase tracking-[0.18em] text-[#006d77]">Konten publik</p><h3 className="mt-2 text-2xl font-semibold">Bagian website utama</h3><p className="mt-2 text-sm text-[#819289]">Edit teks dan kontrol bagian mana yang sedang aktif ditampilkan untuk calon peserta.</p></div><div className="mt-6 divide-y divide-[#e4eee7]">{siteBlocks.map((block) => <div key={block.id} className="grid gap-4 py-5 md:grid-cols-[minmax(0,1fr)_auto] md:items-start"><div className="flex min-w-0 gap-3"><span className={'flex h-9 w-9 shrink-0 items-center justify-center rounded-lg text-xs font-bold ' + (block.published ? 'bg-[#e8f5ed] text-[#006d77]' : 'bg-[#f1f4f1] text-[#819289]')}>{block.published ? 'ON' : 'OFF'}</span><div className="min-w-0 flex-1"><input value={block.label} onChange={(event) => updateSiteBlock(block.id, { label: event.target.value })} className="min-h-9 w-full rounded-lg border border-transparent px-2 text-sm font-semibold outline-none hover:border-[#d4e1d8] focus:border-[#006d77]" /><textarea value={block.description} onChange={(event) => updateSiteBlock(block.id, { description: event.target.value })} rows={2} className="mt-1 w-full resize-none rounded-lg border border-transparent px-2 py-1 text-xs leading-5 text-[#819289] outline-none hover:border-[#d4e1d8] focus:border-[#006d77]" /></div></div><button onClick={() => updateSiteBlock(block.id, { published: !block.published })} className={'min-h-9 rounded-full px-3 text-xs font-bold ' + (block.published ? 'border border-[#c5dacf] text-[#006d77]' : 'bg-[#006d77] text-white')}>{block.published ? 'Nonaktifkan' : 'Aktifkan'}</button></div>)}</div></section>}
  </div>;
};

const Modal = ({ title, description, onClose, children }: { title: string; description?: string; onClose: () => void; children: React.ReactNode }) => <div className="fixed inset-0 z-[80] grid place-items-center bg-[#102c22]/45 px-4 py-6" role="presentation" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }}><section role="dialog" aria-modal="true" aria-labelledby="modal-title" className="max-h-[90dvh] w-full max-w-lg overflow-y-auto rounded-[18px] border border-[#d4e1d8] bg-white p-5 shadow-2xl sm:p-6"><div className="flex items-start justify-between gap-4"><div><h2 id="modal-title" className="text-xl font-semibold">{title}</h2>{description && <p className="mt-1 text-sm leading-6 text-[#819289]">{description}</p>}</div><button onClick={onClose} aria-label="Tutup dialog" title="Tutup" className="flex h-9 w-9 shrink-0 items-center justify-center rounded-full border border-[#cbded0] text-[#607568] hover:bg-[#f3faf5]"><X className="h-4 w-4" /></button></div><div className="mt-5">{children}</div></section></div>;
const Toast = ({ message }: { message: string }) => <div role="status" className="fixed bottom-5 right-5 z-[90] flex max-w-[calc(100vw-2rem)] items-center gap-2 rounded-full bg-[#123d38] px-4 py-3 text-sm font-semibold text-white shadow-xl"><Check className="h-4 w-4 text-[#83c5be]" />{message}</div>;
const AdminStat = ({ label, value, detail }: { label: string; value: string; detail: string }) => <div className="rounded-[18px] border border-[#d4e1d8] bg-white p-5"><p className="text-xs text-[#819289]">{label}</p><p className="mt-2 text-3xl font-semibold text-[#006d77]">{value}</p><p className="mt-1 text-xs text-[#9aa9a0]">{detail}</p></div>;
const AdminQuickAction = ({ title, text, onClick }: { title: string; text: string; onClick: () => void }) => <button onClick={onClick} className="rounded-2xl border border-[#e0ebe3] p-4 text-left hover:border-[#9bc9aa] hover:bg-[#f7fbf8]"><span className="flex items-center justify-between gap-3"><span className="text-sm font-semibold">{title}</span><ArrowRight className="h-4 w-4 text-[#006d77]" /></span><span className="mt-2 block text-xs leading-5 text-[#819289]">{text}</span></button>;
const AdminField = ({ label, value, onChange, placeholder }: { label: string; value: string; onChange: (value: string) => void; placeholder: string }) => <label className="block"><span className="mb-2 block text-sm font-semibold">{label}</span><input value={value} onChange={(event) => onChange(event.target.value)} placeholder={placeholder} className="min-h-11 w-full rounded-xl border border-[#cbded0] bg-white px-4 text-sm outline-none focus:border-[#006d77]" /></label>;
const CatalogCourseCard = ({ course, enrolled, onOpen }: { course: Course; enrolled: boolean; onOpen: () => void }) => <article className="overflow-hidden rounded-[16px] sm:rounded-[18px] border border-[#d4e1d8] bg-white shadow-[0_12px_30px_rgba(35,77,53,0.05)]"><div className={'relative flex h-24 sm:h-36 items-end overflow-hidden p-3 sm:p-5 ' + course.tone}><div className="absolute -right-4 -top-8 h-36 w-36 rotate-12 border-[24px] border-[#006d77]/10" /><div className="absolute bottom-3 right-10 h-8 w-24 border-y border-[#006d77]/15" /><span className="relative rounded-full bg-white/85 px-2 sm:px-3 py-0.5 sm:py-1 text-[9px] sm:text-[10px] font-bold uppercase tracking-[0.12em] text-[#006d77] truncate max-w-[100px] sm:max-w-none">{course.faculty}</span>{enrolled && <span className="absolute right-2.5 top-2.5 sm:right-4 sm:top-4 rounded-full bg-[#006d77] px-2 py-0.5 text-[9px] sm:text-[10px] font-bold text-white">Terdaftar</span>}</div><div className="p-3 sm:p-5"><h3 className="min-h-[32px] sm:min-h-14 text-xs sm:text-lg font-semibold leading-snug line-clamp-2">{course.title}</h3><div className="mt-2 sm:mt-3 grid grid-cols-1 sm:grid-cols-2 gap-1 sm:gap-2 text-[10px] sm:text-xs text-[#819289]"><span className="flex items-center gap-1"><BookOpen className="h-3 w-3 sm:h-3.5 sm:w-3.5 text-[#006d77]" />{course.lessons} materi</span><span className="hidden sm:flex items-center gap-1.5"><CalendarDays className="h-3.5 w-3.5 text-[#006d77]" />{course.schedule.split(',')[0]}</span></div><div className="mt-3 sm:mt-5 flex items-center justify-between text-[10px] sm:text-xs"><span className="text-[#819289]">Progress</span><span className="font-semibold text-[#17231b]">{enrolled ? '68%' : 'Belum dimulai'}</span></div><div className="mt-1.5 sm:mt-2 h-1.5 rounded-full bg-[#e3eee6]"><div className="h-1.5 rounded-full bg-[#006d77]" style={{ width: enrolled ? '68%' : '0%' }} /></div><div className="mt-3 sm:mt-5 flex flex-col sm:flex-row sm:items-center sm:justify-between gap-2 border-t border-[#e5eee7] pt-2.5 sm:pt-4"><span className="text-[10px] sm:text-xs text-[#819289] font-bold sm:font-normal">{enrolled ? 'Aktif' : course.price}</span><button onClick={onOpen} className="flex min-h-8 sm:min-h-9 items-center justify-center gap-1 rounded-lg sm:rounded-full bg-[#e8f5ed] px-2.5 sm:px-3 text-[11px] sm:text-xs font-bold text-[#006d77] hover:bg-[#d6edde]">{enrolled ? 'Lanjutkan' : 'Lihat kelas'} <ArrowRight className="h-3 w-3 sm:h-3.5 sm:w-3.5" /></button></div></div></article>;
const DashboardMetric = ({ icon: Icon, label, value, detail }: { icon: React.ElementType; label: string; value: string; detail: string }) => <div className="flex items-center gap-3 rounded-2xl border border-[#d4e1d8] bg-white p-4"><span className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-[#e8f5ed] text-[#006d77]"><Icon className="h-4 w-4" /></span><div className="min-w-0"><p className="text-xs text-[#819289]">{label}</p><p className="mt-1 text-xl font-semibold text-[#17231b]">{value}</p><p className="truncate text-[10px] text-[#9aa9a0]">{detail}</p></div></div>;
const DashboardCourseCard = ({ course, active, onOpen }: { course: Course; active: boolean; onOpen: () => void }) => <article className="overflow-hidden rounded-[18px] border border-[#d4e1d8] bg-white"><div className={'relative flex h-28 items-end overflow-hidden p-4 ' + course.tone}><div className="absolute right-5 top-4 h-12 w-12 rotate-12 border-[9px] border-[#006d77]/10" /><span className="relative rounded-full bg-white/85 px-2.5 py-1 text-[10px] font-bold uppercase tracking-[0.1em] text-[#006d77]">{course.faculty}</span></div><div className="p-4"><h3 className="min-h-12 text-base font-semibold leading-6">{course.title}</h3><p className="mt-2 text-xs text-[#819289]">{course.tutor}</p><div className="mt-4 h-1.5 rounded-full bg-[#e3eee6]"><div className="h-1.5 rounded-full bg-[#006d77]" style={{ width: active ? '68%' : '0%' }} /></div><div className="mt-2 flex items-center justify-between text-[10px] text-[#819289]"><span>{active ? '68% selesai' : course.duration}</span><button onClick={onOpen} className="flex items-center gap-1 font-bold text-[#006d77]">{active ? 'Lanjutkan' : 'Lihat kelas'} <ArrowRight className="h-3 w-3" /></button></div></div></article>;
const Metric = ({ label, value }: { label: string; value: string }) => <div className="rounded-2xl border border-[#dce9df] bg-white p-5"><p className="text-sm text-[#799083]">{label}</p><p className="mt-2 text-3xl font-semibold text-[#006d77]">{value}</p></div>;
const InfoCard = ({ icon: Icon, title, text }: { icon: React.ElementType; title: string; text: string }) => <div className="flex gap-4 rounded-2xl border border-[#dce9df] bg-white p-5"><span className="flex h-10 w-10 shrink-0 items-center justify-center rounded-full bg-[#edf8f2] text-[#006d77]"><Icon className="h-5 w-5" /></span><div><h3 className="font-semibold">{title}</h3><p className="mt-1 text-sm leading-6 text-[#607568]">{text}</p></div></div>;
const EnrolledCourse = ({ course, onOpen }: { course: Course; onOpen: () => void }) => <article className="rounded-2xl border border-[#dce9df] bg-white p-5"><div className={'flex min-h-28 items-end rounded-xl p-4 ' + course.tone}><span className="rounded-full bg-white/80 px-3 py-1 text-xs font-bold text-[#006d77]">{course.faculty}</span></div><h3 className="mt-5 text-lg font-semibold">{course.title}</h3><div className="mt-4 h-2 rounded-full bg-[#e1eee4]"><div className="h-2 w-[68%] rounded-full bg-[#006d77]" /></div><div className="mt-2 flex justify-between text-xs text-[#799083]"><span>Progress belajar</span><span>68%</span></div><button onClick={onOpen} className="mt-5 flex min-h-10 items-center gap-2 text-sm font-bold text-[#006d77]">Buka ruang belajar <ArrowRight className="h-4 w-4" /></button></article>;
const EmptyBlock = ({ onClick }: { onClick: () => void }) => <div className="rounded-2xl border border-dashed border-[#b9d4c4] bg-white p-7"><div className="flex h-11 w-11 items-center justify-center rounded-full bg-[#edf8f2] text-[#006d77]"><Search className="h-5 w-5" /></div><h3 className="mt-5 text-xl font-semibold">Belum ada kelas aktif</h3><p className="mt-2 max-w-md text-sm leading-6 text-[#607568]">Pilih program muqarrar yang sesuai dengan kebutuhan belajarmu.</p><button onClick={onClick} className="mt-5 flex min-h-10 items-center gap-2 rounded-full bg-[#006d77] px-4 text-sm font-bold text-white">Lihat katalog <ArrowRight className="h-4 w-4" /></button></div>;
const PaymentOption = ({ active, onClick, title, text }: { active: boolean; onClick: () => void; title: string; text: string }) => <button onClick={onClick} className={'flex items-start gap-3 rounded-xl border p-4 text-left transition ' + (active ? 'border-[#83c5be] bg-white/10' : 'border-white/15 hover:border-white/35')}><span className={'mt-0.5 flex h-5 w-5 items-center justify-center rounded-full border ' + (active ? 'border-[#83c5be]' : 'border-white/40')}>{active && <span className="h-2.5 w-2.5 rounded-full bg-[#83c5be]" />}</span><span><span className="block text-sm font-bold">{title}</span><span className="mt-1 block text-xs leading-5 text-[#b7d0c3]">{text}</span></span></button>;
const Row = ({ label, value, strong = false }: { label: string; value: string; strong?: boolean }) => <div className="flex justify-between gap-4"><span className="text-[#799083]">{label}</span><span className={strong ? 'font-bold text-[#006d77]' : 'font-semibold text-right'}>{value}</span></div>;

export default PlatformPage;
